<?php
declare(strict_types=1);
function sc_fail(int $status,string $message): never { throw new ScError($message,$status); }
final class ScError extends RuntimeException {}
function sc_now(): string { return gmdate('Y-m-d\TH:i:s\Z'); }
function sc_today(): string { return (new DateTimeImmutable('now',new DateTimeZone('Europe/Istanbul')))->format('Y-m-d'); }
function sc_max_date(): string { return (new DateTimeImmutable('+90 days',new DateTimeZone('Europe/Istanbul')))->format('Y-m-d'); }
function sc_valid_date(mixed $day): bool { if(!is_string($day)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$day))return false; $d=DateTimeImmutable::createFromFormat('!Y-m-d',$day);return $d!==false&&$d->format('Y-m-d')===$day; }
function sc_minutes(mixed $time): ?int { if(!is_string($time)||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$time))return null;return (int)substr($time,0,2)*60+(int)substr($time,3,2); }
function sc_clock(int $n): string { return sprintf('%02d:%02d',intdiv($n,60),$n%60); }
function sc_future(string $date,string $time): bool { return (new DateTimeImmutable($date.'T'.$time.':00',new DateTimeZone('Europe/Istanbul')))->getTimestamp()>time(); }
function sc_phone(mixed $value): string { $s=preg_replace('/[\s()+-]/','',(string)$value);return str_starts_with($s,'90')?'0'.substr($s,2):$s; }
function sc_uuid(): string { $b=random_bytes(16);$b[6]=chr((ord($b[6])&0x0f)|0x40);$b[8]=chr((ord($b[8])&0x3f)|0x80);$x=bin2hex($b);return substr($x,0,8).'-'.substr($x,8,4).'-'.substr($x,12,4).'-'.substr($x,16,4).'-'.substr($x,20); }
function sc_schedule(): array { return array_fill(0,7,['enabled'=>true,'start'=>'09:00','end'=>'22:00','breakEnabled'=>false,'breakStart'=>'','breakEnd'=>'']); }
function sc_full_barber(array $b): array { return array_replace(['photo'=>'','phone'=>'','instagram'=>'','email'=>'','bio'=>'','duration'=>60,'schedule'=>sc_schedule(),'daysOff'=>[],'active'=>true,'archived'=>false],$b); }
function sc_initial_business(): array { $barbers=[];foreach(['Kadircan','Davut','Alperen','Enescan'] as $i=>$name)$barbers[]=sc_full_barber(['id'=>$i+1,'name'=>$name,'initials'=>substr($name,0,1),'specialty'=>'Saç kesimi & bakım']);$barbers[0]['schedule'][1]['start']='18:00';$barbers[3]['schedule'][2]['start']='18:00';return ['name'=>'Davut Şencan Hair Studio','description'=>'Kendinize bir saat ayırın. Gerisini bize bırakın.','phone'=>'','address'=>'','barbers'=>$barbers,'scheduleRevision'=>1,'brandNameRevision'=>1]; }
function sc_barber(array $input,array $previous=[]): array {
 $b=sc_full_barber(array_replace($previous,$input));foreach(['name','specialty','bio','phone','instagram','email'] as $k){if(!is_string($b[$k]))sc_fail(400,'Çalışan bilgileri geçersiz.');$b[$k]=trim($b[$k]);}
 if(mb_strlen($b['name'])<2||mb_strlen($b['name'])>80||mb_strlen($b['specialty'])>200||mb_strlen($b['bio'])>600||strlen($b['phone'])>30||strlen($b['instagram'])>60)sc_fail(400,'Çalışan adı veya açıklamalar çok uzun / eksik.');
 if(strlen($b['email'])>254||($b['email']!==''&&!filter_var($b['email'],FILTER_VALIDATE_EMAIL)))sc_fail(400,'Geçerli bir çalışan e-posta adresi girin.');
 $b['instagram']=ltrim($b['instagram'],'@');$b['duration']=(int)$b['duration'];if(!in_array($b['duration'],[15,30,45,60,90,120],true))sc_fail(400,'Randevu süresi geçersiz.');
 if(!is_string($b['photo'])||strlen($b['photo'])>400000||($b['photo']!==''&&!preg_match('~^data:image/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$~D',$b['photo'])))sc_fail(400,'Küçük bir JPG, PNG veya WebP fotoğrafı seçin.');
 if(!is_array($b['schedule'])||!array_is_list($b['schedule'])||count($b['schedule'])!==7)sc_fail(400,'7 günlük çalışma saati gerekli.');
 foreach($b['schedule'] as $i=>$s){if(!is_array($s))sc_fail(400,'Günlük saatler geçersiz.');$r=['enabled'=>!empty($s['enabled']),'start'=>$s['start']??'09:00','end'=>$s['end']??'22:00','breakEnabled'=>!empty($s['breakEnabled']),'breakStart'=>$s['breakStart']??'','breakEnd'=>$s['breakEnd']??''];if(!$r['breakEnabled']){$r['breakStart']='';$r['breakEnd']='';}if($r['enabled']){$st=sc_minutes($r['start']);$en=sc_minutes($r['end']);if($st===null||$en===null||$en-$st<$b['duration'])sc_fail(400,($i+1).'. günün çalışma saatlerini kontrol edin.');if($r['breakEnabled']){$bs=sc_minutes($r['breakStart']);$be=sc_minutes($r['breakEnd']);if($bs===null||$be===null||$bs>=$be||$bs<$st||$be>$en)sc_fail(400,($i+1).'. günün mola saatlerini kontrol edin.');}}$b['schedule'][$i]=$r;}
 if(!is_array($b['daysOff'])||count($b['daysOff'])>180)sc_fail(400,'İzin tarihleri geçersiz.');foreach($b['daysOff'] as $day)if(!sc_valid_date($day))sc_fail(400,'İzin tarihleri geçersiz.');$b['daysOff']=array_values(array_unique($b['daysOff']));sort($b['daysOff']);$b['active']=$b['active']!==false;$b['archived']=!empty($b['archived']);$parts=preg_split('/\s+/u',$b['name']);$b['initials']=mb_strtoupper(implode('',array_map(fn($p)=>mb_substr($p,0,1),array_slice($parts,0,2))),'UTF-8');return $b;
}
function sc_services(): array { return [
 ['id'=>'hair','category'=>'hair','name'=>'Saç','price'=>600],['id'=>'beard','category'=>'hair','name'=>'Sakal','price'=>300],['id'=>'hair-beard','category'=>'hair','name'=>'Saç + Sakal','price'=>800],['id'=>'perm','category'=>'hair','name'=>'Perma','price'=>2500,'from'=>true],['id'=>'child','category'=>'hair','name'=>'Çocuk tıraşı','price'=>400],['id'=>'dye','category'=>'hair','name'=>'Boya işlemleri','price'=>800],['id'=>'color','category'=>'hair','name'=>'Renklendirme','price'=>2000,'from'=>true],['id'=>'keratin','category'=>'care','name'=>'Keratin bakımı','price'=>2000,'from'=>true],['id'=>'skin','category'=>'care','name'=>'Detaylı cilt bakımı','price'=>900],['id'=>'hair-care','category'=>'care','name'=>'Saç bakımı','price'=>500],['id'=>'mask','category'=>'care','name'=>'Maske','price'=>300],['id'=>'peeling','category'=>'care','name'=>'Peeling','price'=>300]]; }
function sc_quote(mixed $ids): array { $catalog=sc_services();if(!is_array($ids)||!array_is_list($ids)||count($ids)<1||count($ids)>count($catalog))sc_fail(400,'En az bir geçerli hizmet seçin.');foreach($ids as $id)if(!is_string($id)||!in_array($id,array_column($catalog,'id'),true))sc_fail(400,'En az bir geçerli hizmet seçin.');$items=[];$total=0;$from=false;foreach($catalog as $s)if(in_array($s['id'],$ids,true)){$s['from']=!empty($s['from']);$items[]=$s;$total+=$s['price'];$from=$from||$s['from'];}return ['services'=>$items,'total'=>$total,'priceFrom'=>$from]; }
function sc_slots(?array $b,string $date,array $records): array {
 if(!$b||empty($b['active'])||!empty($b['archived'])||!sc_valid_date($date)||in_array($date,$b['daysOff'],true))return [];
 $i=(int)(new DateTimeImmutable($date))->format('N')-1;$s=$b['schedule'][$i];if(empty($s['enabled']))return [];$start=sc_minutes($s['start']);$end=sc_minutes($s['end']);$duration=$b['duration'];$bs=!empty($s['breakEnabled'])?sc_minutes($s['breakStart']):null;$be=!empty($s['breakEnabled'])?sc_minutes($s['breakEnd']):null;$ranges=$bs!==null?[[$start,$bs],[$be,$end]]:[[$start,$end]];$result=[];
 foreach($ranges as [$from,$to])for($n=$from;$n+$duration<=$to;$n+=$duration){$clock=sc_clock($n);$available=sc_future($date,$clock);if($available)foreach($records as $a)if($a['barberId']===$b['id']&&$a['date']===$date&&$a['status']!=='cancelled'&&sc_minutes($a['time'])<$n+$duration&&sc_minutes($a['time'])+($a['duration']??60)>$n){$available=false;break;}$result[]=['time'=>$clock,'duration'=>$duration,'available'=>$available];}return $result;
}

function sc_public_barbers(array $barbers): array { return array_map(function($b){unset($b['email']);return $b;},$barbers); }
